def apply(path,pairs,label,skip_marker):
    s=io.open(path,encoding="utf-8").read()
    if skip_marker in s:
        print("ZATEN VAR — %s (%s), atlandi"%(label,skip_marker)); return
    for o64,n64 in pairs:
        o=base64.b64decode(o64).decode(); n=base64.b64decode(n64).decode()
        if n in s and o not in s: continue
        c=s.count(o); assert c==1, "%s anchor=%d :: %s"%(label,c,o[:60])
        s=s.replace(o,n,1)
    if not os.path.exists(path+".notbak"):
        io.open(path+".notbak","w",encoding="utf-8").write(io.open(path,encoding="utf-8").read())
    io.open(path,"w",encoding="utf-8").write(s); print("OK",label)
